<template><view class="page">
 <template v-if="!id"><button type="primary" @click="creating=true">新建案件</button><input v-model="keyword" placeholder="搜索标题、案由、客户" @confirm="load(false)" placeholder-style="color:#606266;font-size:16px;"/><button :disabled="loading" @click="load(false)">查询</button><view v-for="item in rows" :key="item.id" class="card" @click="show(item.id)"><text class="title">{{item.title}}</text><text>{{item.status}} · {{item.caseType || '未填案由'}}</text><text>{{item.clientName || '未填客户'}}</text><text :class="item.status==='进行中' ? dateClass(item.nextHearingDate) : ''">关键日期：{{item.nextHearingDate || '未设置'}}</text><text :class="item.status==='进行中' ? dateClass(item.limitationDate) : ''">时效日期：{{item.limitationDate || '未设置'}}</text></view><text v-if="!rows.length && !loading">暂无案件，请新建</text><button v-if="more" :loading="loading" @click="load(true)">加载更多</button></template>
 <template v-else-if="detail"><button @click="back">返回列表</button><text class="title">{{detail.caseInfo.title}}</text><work-timer :key="$store.state.token" :case-id="id" /><view class="card"><text v-for="(label,key) in labels" :key="key">{{label}}：{{detail.caseInfo[key] || '未填写'}}</text></view><button type="primary" :loading="busy" :disabled="busy" @click="consult">开始咨询</button><case-archive :key="$store.state.token" :case-id="id" /><text class="title">关联会话与审查</text><view v-for="item in detail.sessions" :key="item.id" class="card" @click="openSession(item)">{{item.sessionTitle || '会话'}} ›</view><text v-if="!detail.sessions.length">暂无关联记录，从案件开始咨询</text></template>
 <text v-if="loading">加载中…</text><text v-if="error" class="error">{{error}}</text><button v-if="error" :disabled="loading" @click="retry">重试</button>
 <view v-if="creating" class="form"><text class="title">新建案件</text><input :disabled="busy" v-model="form.title" maxlength="200" placeholder="案件标题（必填）"/><input :disabled="busy" v-model="form.caseType" maxlength="100" placeholder="案由"/><input :disabled="busy" v-model="form.clientName" maxlength="200" placeholder="客户"/><text>下次关键日期</text><picker :disabled="busy" mode="date" :value="form.nextHearingDate || ''" @change="hearing"><view class="date">{{form.nextHearingDate || '选择日期'}}</view></picker><button size="mini" :disabled="busy" @click="form.nextHearingDate=null">清空</button><text>诉讼时效日期</text><picker :disabled="busy" mode="date" :value="form.limitationDate || ''" @change="limitation"><view class="date">{{form.limitationDate || '选择日期'}}</view></picker><button size="mini" :disabled="busy" @click="form.limitationDate=null">清空</button><text class="error">{{formError}}</text><button :loading="busy" :disabled="busy" type="primary" @click="save">保存</button><button :disabled="busy" @click="creating=false">取消</button></view>
</view></template>
<script>
import {caseApi} from '@/common/api/cases';
import {createLegalSession,rememberLegalContext} from '@/common/api/legal-entry';
import {normalizeSessionId} from '@/common/api/session';
export default{data(){return{id:'',detail:null,rows:[],page:0,more:false,loading:false,busy:false,error:'',retryMore:false,keyword:'',creating:false,formError:'',form:{title:'',caseType:'',clientName:'',status:'进行中',nextHearingDate:null,limitationDate:null},labels:{status:'状态',caseType:'案由',clientName:'客户',oppositeParty:'对方',court:'法院',nextHearingDate:'关键日期',limitationDate:'时效日期',description:'案情摘要'}};},onLoad(o){this.id=normalizeSessionId(o.id);},onShow(){const owner=uni.getStorageSync('token');if(this._owner!==owner){this._owner=owner;this._version=(this._version||0)+1;this.rows=[];this.detail=null;this.page=0;this.loading=false;this.creating=false;this.error='';this.retryMore=false;this.form={title:'',caseType:'',clientName:'',status:'进行中',nextHearingDate:null,limitationDate:null};}this.retry();},onUnload(){this._version=(this._version||0)+1;},async onPullDownRefresh(){try{await (this.id?this.loadDetail():this.load(false));}finally{uni.stopPullDownRefresh();}},onReachBottom(){if(!this.id&&this.more)this.load(true);},methods:{dateClass(date){if(!date)return '';const now=new Date(Date.now()+8*3600000).toISOString().slice(0,10);const days=(Date.parse(date+'T00:00:00+08:00')-Date.parse(now+'T00:00:00+08:00'))/86400000;return days>=0&&days<=3?'danger':days>=0&&days<=7?'warning':'';},hearing(e){this.form.nextHearingDate=e.detail.value;},limitation(e){this.form.limitationDate=e.detail.value;},show(id){uni.navigateTo({url:'/pages/cases/index?id='+encodeURIComponent(id)});},back(){this.id='';this.detail=null;this.load(false);},retry(){return this.id?this.loadDetail():this.load(Boolean(this.error&&this.retryMore));},async load(append=false){if(this.loading)return;this.loading=true;this.error='';const version=this._version=(this._version||0)+1,next=append?this.page+1:1;try{const result=await caseApi(this.$request,'/list','GET',{keyword:this.keyword,pageNum:next,pageSize:20});if(version!==this._version)return;this.rows=append?this.rows.concat(result.rows):result.rows;this.page=next;this.more=next*20<Number(result.total);}catch(e){if(version===this._version){this.error=e.message;this.retryMore=append;}}finally{if(version===this._version)this.loading=false;}},async loadDetail(){if(this.loading)return;this.loading=true;this.error='';const version=this._version=(this._version||0)+1;try{const result=await caseApi(this.$request,'/'+this.id);if(version===this._version)this.detail=result.data;}catch(e){if(version===this._version){this.error=e.message;this.detail=null;}}finally{if(version===this._version)this.loading=false;}},async save(){if(this.busy)return;if(!this.form.title.trim()){this.formError='请填写案件标题';return;}this.busy=true;this.formError='';try{const result=await caseApi(this.$request,'','POST',{...this.form,title:this.form.title.trim()});this.creating=false;this.id=String(result.data);await this.loadDetail();}catch(e){this.formError=e.message;}finally{this.busy=false;}},async consult(){if(this.busy||!this.detail)return;this.busy=true;try{const result=await createLegalSession(this.$request,uni,{caseId:this.id,sessionTitle:'案件咨询 - '+this.detail.caseInfo.title});uni.navigateTo({url:result.url});}catch(e){this.error=e.message;}finally{this.busy=false;}},async openSession(item){if(this.busy)return;if(/^合同(审查|快审)/.test(item.sessionTitle||'')){uni.navigateTo({url:'/pages/index/quick-review?sessionId='+encodeURIComponent(item.id)});return;}this.busy=true;try{const name=/^文书/.test(item.sessionTitle||'')?'文书起草助手':'法律咨询助手';const result=await this.$request('/agent/agent/agentOptions','GET',{}, {'content-type':'application/json'});const agent=result.data&&result.data.find(a=>a.agentName===name&&String(a.status)==='0');if(!agent)throw new Error('法律助手暂不可用');rememberLegalContext(uni,String((uni.getStorageSync('userInfo')||{}).userId||''),item.id,{agentId:agent.id,appName:name});uni.navigateTo({url:'/pages/index/index?sessionId='+encodeURIComponent(item.id)+'&agentId='+encodeURIComponent(agent.id)+'&appName='+encodeURIComponent(name)});}catch(e){this.error=e.message;}finally{this.busy=false;}}}};
</script>
<style scoped>.card .danger{color:#c63737}.card .warning{color:#aa6500}.page{padding:30rpx;background:#f5f7f6;min-height:100vh}.title{display:block;font-size:20px;font-weight:600;margin:24rpx 0}.card{background:white;border-radius:18rpx;padding:28rpx;margin:22rpx 0}.card text{display:block;margin:14rpx 0;font-size:16px}.error{display:block;color:#b43d3d;margin:20rpx 0}button{font-size:16px;margin:16rpx 0}input,.date{padding:24rpx;background:white;margin:20rpx 0;border-radius:12rpx}.form{background:#eef5f0;padding:24rpx;margin:24rpx 0}.form>text{display:block}</style>

<style scoped lang="scss">
@import '@/common/form-controls.scss';
input { @include native-input-frame; border:1px solid var(--brand-border); } .date { box-sizing:border-box; min-height:48px; padding:12px; font-size:16px; line-height:24px; }
</style>
